/**
 * #1252 — a reader-layout BRD without auto-update gives a visible sign that
 * the approved requirements it lists have changed since its latest version.
 *
 * An auto-update document is regenerated by the check
 * (`approved-requirements-staleness.ts`); one without auto-update (the
 * default, `GeneratedDocument.autoUpdate`) never is, so approving or editing a
 * requirement used to change nothing the analyst could see. Nothing new
 * decides what "changed" means: the latest version's input snapshot recorded
 * its approved requirements (`APPROVED_REQUIREMENTS_ITEM`, a hash of the
 * fields the section shows), and this compares it with the same item taken
 * now. A code-link change or a write that bumps only `version` moves neither.
 */
import { prisma } from "../prisma.js";
import { createChildLogger } from "../logger.js";
import { readsApprovedRequirements } from "./approved-requirements-section.js";
import { approvedRequirementsItem } from "./generation-inputs.js";
import { parseGeneratedDocVersionManifest } from "./generated-doc-provenance.js";
import { APPROVED_REQUIREMENTS_ITEM } from "./regeneration-plan.js";

const log = createChildLogger("docs-gen-approved-requirements-currency");

/**
 * The statuses of a document that shows a published version and has no run
 * going: a running, pending or cancelling one captures its inputs afresh, and
 * a failed or cancelled one already offers a regenerate of its own.
 */
const SETTLED_STATUSES: ReadonlySet<string> = new Set(["ready", "degraded"]);

/** What of a `GeneratedDocument` row the check reads. */
export interface ApprovedRequirementsCurrencyDoc {
  id: string;
  projectId: string;
  scope: string;
  scopeFilter: string;
  autoUpdate: boolean;
  status: string;
}

/**
 * Whether `doc` is a settled reader BRD without auto-update whose approved
 * requirements changed since its latest version. False whenever that cannot
 * be told: no published version, or one published before its snapshot
 * recorded approved requirements (#1230). Never throws: a failed read is
 * logged and reads as not out of date, so it cannot break opening a document.
 */
export async function approvedRequirementsOutOfDate(
  doc: ApprovedRequirementsCurrencyDoc,
): Promise<boolean> {
  if (doc.autoUpdate || !SETTLED_STATUSES.has(doc.status)) return false;
  if (!readsApprovedRequirements(doc)) return false;
  try {
    const latest = await prisma.generatedDocumentVersion.findFirst({
      where: { documentId: doc.id, document: { projectId: doc.projectId } },
      orderBy: { version: "desc" },
      select: { provenanceManifest: true },
    });
    if (!latest?.provenanceManifest) return false;
    const recorded = parseGeneratedDocVersionManifest(latest.provenanceManifest).inputSnapshot
      ?.items[APPROVED_REQUIREMENTS_ITEM];
    if (recorded === undefined) return false;
    return recorded !== (await approvedRequirementsItem(doc.projectId));
  } catch (err) {
    log.warn("Could not tell whether a reader BRD's approved requirements changed", {
      docId: doc.id,
      projectId: doc.projectId,
      error: (err as Error).message,
    });
    return false;
  }
}
